From 6cf0cdf60ef21b595791dabbc962208b807dcf30 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:49:58 +0100
Subject: [PATCH] libtaskmanager: put the window ids of grouped tasks in their
 drag data

Dragging a grouped task carried no window ids, so dropping it on another
activity in the Activity Manager sidebar did nothing even where a single
window works. The group now lists the ids of its windows in the drag data.

BUG: 450341
---
 libtaskmanager/taskgroupingproxymodel.cpp | 18 +++++++++++++-----
 libtaskmanager/waylandtasksmodel.cpp      | 16 +++++++++++++---
 2 files changed, 26 insertions(+), 8 deletions(-)

diff --git a/libtaskmanager/taskgroupingproxymodel.cpp b/libtaskmanager/taskgroupingproxymodel.cpp
index 82709a40c9..ac3b58ecda 100644
--- a/libtaskmanager/taskgroupingproxymodel.cpp
+++ b/libtaskmanager/taskgroupingproxymodel.cpp
@@ -680,12 +680,20 @@ QVariant TaskGroupingProxyModel::data(const QModelIndex &proxyIndex, int role) c
             return winIds;
         }

-        case AbstractTasksModel::MimeType:
-            return QStringLiteral("windowsystem/multiple-winids");
+        case AbstractTasksModel::MimeType: {
+            QString mimeType = index(0, 0, proxyIndex).data(AbstractTasksModel::MimeType).toString();
+            return mimeType.replace(QLatin1String("windowsystem/winid"), QLatin1String("windowsystem/multiple-winids"));
+        }

-        case AbstractTasksModel::MimeData:
-            // FIXME TODO: Implement.
-            return {};
+        case AbstractTasksModel::MimeData: {
+            QStringList winIds;
+
+            for (int i = 0; i < rowCount(proxyIndex); ++i) {
+                winIds.append(index(i, 0, proxyIndex).data(AbstractTasksModel::MimeData).toString());
+            }
+
+            return winIds.join(QLatin1Char('\n'));
+        }

         case AbstractTasksModel::IsGroupParent:
             return true;
diff --git a/libtaskmanager/waylandtasksmodel.cpp b/libtaskmanager/waylandtasksmodel.cpp
index ed0b90cbbf..eef36ba84e 100644
--- a/libtaskmanager/waylandtasksmodel.cpp
+++ b/libtaskmanager/waylandtasksmodel.cpp
@@ -1368,9 +1368,19 @@ QList<QUuid> WaylandTasksModel::winIdsFromMimeData(const QMimeData *mimeData, bo
         return ids;
     }

-    // FIXME: Extracting multiple winids is still unimplemented;
-    // TaskGroupingProxy::data(..., ::MimeData) can't produce
-    // a payload with them anyways.
+    const QList<QByteArray> data = mimeData->data(Private::groupMimeType()).split('\n');
+
+    for (const QByteArray &idData : data) {
+        QUuid id(idData);
+
+        if (!id.isNull()) {
+            ids << id;
+        }
+    }
+
+    if (ok) {
+        *ok = !ids.isEmpty();
+    }

     return ids;
 }
